ALTER TABLE "google_commands" DROP CONSTRAINT "google_commands_operation_ck", ADD CONSTRAINT "google_commands_operation_ck" CHECK ("operation" in ('create', 'move', 'cancel', 'restore', 'move_series', 'end_series', 'event_create', 'event_update', 'event_delete', 'assign') and (jsonb_typeof("plan") = 'object' and "plan"->>'version' = '1' and "plan"->'input'->>'operation' = "operation") is true);